  "Cada acción de la sesión queda registrada con hora de planta, actor y vista. No se edita ni se borra desde la consola; solo «Reiniciar demo» empieza un registro nuevo.": "Each action of the session is recorded with time of floor, actor and view. It is not edited or deleted from the console; only \"Reboot demo\" begins a new record.",
  "Exportar JSON": "Export JSON",
  "Qué es": "What it is",
  "Una simulación interactiva de la consola de Prodigy, la plataforma de agentes de Ciklum, configurada para Congelados de Navarra. Se abre en el navegador, sin instalación y sin acceso a sistemas de Congelados de Navarra.": "An interactive simulation of Prodigy, Ciklum's agent platform, configured for Congelados de Navarra. It runs in your browser, with no installation and no access to Congelados de Navarra's systems.",
  "Datos": "Data",
  "Lotes, palés (SSCC), lecturas, reclamaciones y procedimientos son sintéticos y coherentes entre sí. Los ha preparado Ciklum para esta demostración; no proceden de Congelados de Navarra.": "Lots, pallets (SSCC), readings, complaints and procedures are synthetic and consistent across the demo. Ciklum prepared them for this demonstration; they are not Congelados de Navarra's operational data.",
  "Acciones": "Actions",
  "Bloqueos, tickets, envíos y publicaciones se simulan y no salen de este navegador. Todo queda en el registro de auditoría de la sesión y se borra con «Reiniciar demo».": "Holds, tickets, messages and publications are simulated within this browser. They appear in the session audit log and are cleared by “Reset demo”.",
  "Conectores": "Connectors",
  "SAP (SAP QM), MES Mapex, Siemens Opcenter APS, Mecalux Easy WMS, Galileo/SCADA, Elara y Microsoft 365 aparecen como conectores de demostración. En un piloto se conectan uno o dos sistemas en modo lectura.": "SAP (SAP QM), MES Mapex, Siemens Opcenter APS, Mecalux Easy WMS, Galileo / SCADA, Elara and Microsoft 365 appear as demonstration connectors. One or two systems are connected in reading mode on a pilot.",
  "De serie y a medida": "Built-in capabilities and customisation",
  "De serie en Prodigy: agentes y workflows (Routines) con editor, aprobación humana, registro de auditoría, respuestas con citas y control de coste por petición. Representado en esta demo: el generador de workflows desde texto y los agentes de planta. Su integración en Prodigy y los conectores se validan en el piloto.": "Prodigy provides agents, workflows (Routines) with an editor, human approval, auditing, source citations and per-request cost controls. This demo represents text-to-workflow generation and plant agents. Their integration into Prodigy and the required connectors are validated in the pilot.",
  "Esta página no llama a ningún modelo: las respuestas están preparadas. En un piloto, el modelo lo elige Congelados de Navarra (Azure OpenAI, Gemini o un modelo local) y Prodigy se instala en su infraestructura.": "This page does not call a model: its responses are prepared. In a pilot, Congelados de Navarra chooses the model (Azure OpenAI, Gemini or a local model), and Prodigy is installed on its infrastructure.",
