  "se retira ⟦0⟧. Motivo: «⟦1⟧»": "⟦0⟧ is removed. Reason: “⟦1⟧”",
  "Motivo del rechazo:": "Reason for rejection:",
  "Bloqueo de calidad · ⟦0⟧ palés en ⟦1⟧": "Quality hold · ⟦0⟧ pallets in ⟦1⟧",
  "Motivo: aire por encima de ⟦0⟧ durante ⟦1⟧ min (⟦2⟧–⟦3⟧), más de los ⟦4⟧ min que fija ⟦5⟧⟦6⟧. Se bloquean los palés expuestos hasta medir la temperatura de producto y decidir el destino de cada lote.": "Reason: air above ⟦0⟧ for ⟦1⟧ min (⟦2⟧–⟦3⟧), exceeding the ⟦4⟧ min set by ⟦5⟧⟦6⟧. Exposed pallets are placed on hold pending product-temperature checks and a disposition decision for each lot.",
  "el workflow": "the workflow",
  ", y ⟦0⟧ min por encima de ⟦1⟧: excursión crítica": ", and ⟦0⟧ min above ⟦1⟧: a critical excursion",
  "PNT-CAL-012 · PNT-CAL-015 · solo Calidad libera": "PNT-CAL-012 · PNT-CAL-015 · Only Quality releases",
  "Aplicando en SAP QM, Easy WMS, Elara y Teams…": "Applying in SAP QM, Easy WMS, Elara and Teams...",
  "Propuesta de bloqueo": "Proposal of hold",
  "La prepara el agente ⟦0⟧": "agent ⟦0⟧",
  "Aparecerá aquí para su aprobación. Nada se escribe en SAP QM ni en Easy WMS sin la decisión de Calidad.": "He'll show up here for his approval. Nothing is written in SAP QM or Easy WMS without the Quality decision.",
  "Antecedente en Elara: ⟦0⟧ (⟦1⟧), ⟦2⟧ para ⟦3⟧: ⟦4⟧ por ⟦5⟧ (⟦6⟧, ⟦7⟧); tenerlo en cuenta al decidir el destino de ⟦8⟧.": "Antecedent in Elara: ⟦0⟧ (⟦1⟧), ⟦2⟧ for ⟦3⟧: ⟦4⟧ for ⟦5⟧ (⟦6⟧, ⟦7⟧); take it into account when deciding the destination of ⟦8⟧.",
  "Líder: ⟦0⟧. Equipo: ⟦1⟧, ⟦2⟧ y ⟦3⟧.": "Leader: ⟦0⟧. Equipment: ⟦1⟧, ⟦2⟧ and ⟦3⟧.",
  "Descripción del problema": "Description of the problem",
  "El ⟦0⟧ el aire de la cámara ⟦1⟧ superó ⟦2⟧ durante ⟦3⟧ min (⟦4⟧–⟦5⟧), con un pico de ⟦6⟧ a las ⟦7⟧ y ⟦8⟧ min por encima de ⟦9⟧. Había ⟦10⟧ palés de ⟦11⟧ lotes en la cámara.⟦12⟧": "On ⟦0⟧, the air in cold room ⟦1⟧ exceeded ⟦2⟧ for ⟦3⟧ min (⟦4⟧–⟦5⟧), peaking at ⟦6⟧ at ⟦7⟧, with ⟦8⟧ min above ⟦9⟧. There were ⟦10⟧ pallets from ⟦11⟧ lots in the room.⟦12⟧",
  "Contención": "Containment",
  "⟦0⟧: ⟦1⟧ palés bloqueados en SAP QM e inmovilizados en Easy WMS; ⟦2⟧ expediciones retenidas. Medir la temperatura de producto con sonda (capa exterior y centro) en los palés expuestos. ⟦3⟧": "⟦0⟧: ⟦1⟧ pallets blocked in SAP QM and immobilized in Easy WMS; ⟦2⟧ shipments retained. Measuring the product temperature with probe (outer layer and centre) in the pallets exposed. ⟦3⟧",
  "Evaluar los ⟦0⟧ palés de los mismos lotes en silos, que no estuvieron en ⟦1⟧.": "To evaluate the ⟦0⟧ pallets of the same lots silos, which were not in ⟦1⟧.",
  "Causa raíz (hipótesis)": "Root cause (hypothesis)",
  "Acciones correctivas propuestas": "Proposed corrective actions",
  "Revisar el cierre de la puerta rápida ⟦0⟧ y su sensor; revisar la programación del desescarche de ⟦1⟧ frente a la actividad del muelle; valorar un aviso de puerta abierta en Galileo.": "Review the closing of the ⟦0⟧ fast door and its sensor; review the defrost ⟦1⟧ programming against the activity of the dock; assess an open door notice at Galileo.",
  "Implantación y verificación": "Implementation and verification",
  "Verificar el cierre de ⟦0⟧ y la recuperación de temperatura en el siguiente ciclo de desescarche. Decisión de destino por lote según PNT-CAL-012: liberar, reclasificar o destruir.": "Check the ⟦0⟧ closure and temperature recovery in the next defrost cycle. Decision of destination for lot according to PNT-CAL-012: release, reclassify or destroy.",
  "Prevención": "Prevention",
  "Extender la revisión de puertas y desescarches al resto de cámaras de expedición de Fustiñana y actualizar la instrucción de desescarche si procede.": "Extend the review of doors and defrost to the rest of cold rooms of dispatch of Fustiñana and update the instruction of defrost if applicable.",
  "Cerrar ⟦0⟧ tras verificar la eficacia y registrar la decisión de destino de los ⟦1⟧ lotes.": "Close ⟦0⟧ after checking the effectiveness and record the destination decision of the ⟦1⟧ lots.",
  "canal «⟦1⟧»": "channel \"⟦1⟧\"",
  "Bloqueo de calidad ⟦4⟧ en ⟦5⟧, aprobado por ⟦6⟧ a las ⟦7⟧. No cargar hasta nueva decisión de Calidad:": "Quality hold ⟦4⟧ in ⟦5⟧, approved for ⟦6⟧ at ⟦7⟧. Do not load until new Quality decision:",
  "Revisar el cierre de la puerta ⟦10⟧ y el desescarche de ⟦11⟧ (hipótesis de causa). Detalle en ⟦12⟧ (Elara).": "Check door closure ⟦10⟧ and defrost of ⟦11⟧ (cause hypothesis). Detail in ⟦12⟧ (Elara).",
  "Siguiente paso según PNT-CAL-012: medir la temperatura de producto con sonda en los palés expuestos, capa exterior y centro.": "Next step according to PNT-CAL-012: measure product temperature with probe in the pallets exposed, outer layer and center.",
