  "Con estos parámetros la alarma ⟦0⟧ no activa el bloqueo: no se ha propuesto ni aplicado ninguna acción en SAP QM, Easy WMS, Elara ni Teams.": "With these parameters the alarm ⟦0⟧ does not activate the hold: no action has been proposed or applied in SAP QM, Easy WMS, Elara or Teams.",
