  "Fecha de aprobación": "Date of approval",
  "1. Descripción del evento": "1. Description of the event",
  "El ⟦0⟧ a las ⟦1⟧, SCADA Galileo emitió la alarma ⟦2⟧ en la cámara ⟦3⟧ (⟦4⟧, consigna ⟦5⟧). La temperatura de aire (sonda ⟦6⟧) estuvo ⟦7⟧ min por encima de ⟦8⟧ (⟦9⟧–⟦10⟧), con un pico de ⟦11⟧ a las ⟦12⟧ y ⟦13⟧ min por encima de ⟦14⟧. A las ⟦15⟧ la cámara estaba a ⟦16⟧. Criterio aplicado: PNT-CAL-012 (bloqueo de los palés expuestos si el aire supera ⟦17⟧ durante más de ⟦18⟧ min) y PNT-CAL-015 (registro del bloqueo en SAP QM y Easy WMS; solo Calidad libera).": "On ⟦0⟧ at ⟦1⟧, SCADA Galileo raised alarm ⟦2⟧ in cold room ⟦3⟧ (⟦4⟧, setpoint ⟦5⟧). Air temperature (sensor ⟦6⟧) was above ⟦8⟧ for ⟦7⟧ min (⟦9⟧–⟦10⟧), peaking at ⟦11⟧ at ⟦12⟧, with ⟦13⟧ min above ⟦14⟧. At ⟦15⟧, room temperature was ⟦16⟧. Applied criteria: PNT-CAL-012 (hold exposed pallets if air exceeds ⟦17⟧ for more than ⟦18⟧ min) and PNT-CAL-015 (record the hold in SAP QM and Easy WMS; only Quality may release it).",
  "2. Lecturas por encima del límite": "2. Reading above the limit",
  "Por encima de ⟦0⟧": "Over ⟦0⟧",
  "3. Eventos de la cámara": "3. Events of cold room",
  "Equipo o referencia": "Equipment or reference",
  "Evento": "Event",
  "4. Alcance del bloqueo": "4. Scope of hold",
  "Expedición retenida": "Dispatch retained",
  "4 bis. Lotes retirados del alcance": "4 bis. Lots withdrawn from range",
  "⟦0⟧. Motivo indicado por ⟦1⟧: «⟦2⟧».": "⟦0⟧. Reason for ⟦1⟧: \"⟦2⟧ '.",
  "5. Mismos lotes fuera de la cámara": "5. Same lots out of cold room",
  "6. Palés expedidos antes de la alarma (fuera del alcance)": "6. Pallets dispatched before the alarm (out of range)",
  "7. Acciones aplicadas tras la aprobación": "7. Actions implemented after approval",
  "SAP QM · ⟦0⟧: bloqueo de calidad de ⟦1⟧ lotes (⟦2⟧ palés, ⟦3⟧; ⟦4⟧ a coste estándar).": "SAP QM · ⟦0⟧: quality hold of ⟦1⟧ lots (⟦2⟧ pallets, ⟦3⟧, ⟦4⟧ to cost standard).",
  "Mecalux Easy WMS: ⟦0⟧ SSCC inmovilizados; expediciones retenidas: ⟦1⟧.": "Mecalux Easy WMS: ⟦0⟧ SSCC immobilised; shipments retained: ⟦1⟧.",
  "Elara · ⟦0⟧: no conformidad abierta con borrador de 8D (⟦1⟧).": "Elara · ⟦0⟧: non-conformity open with draft of 8D (⟦1⟧).",
  "Microsoft Teams: aviso a ⟦0⟧ y ⟦1⟧ en el canal «⟦2⟧».": "Microsoft Teams: notice to ⟦0⟧ and ⟦1⟧ on the channel \"⟦2⟧.\"",
  "8. Hipótesis de causa y acciones pendientes": "8. Case scenario and pending actions",
  "Antecedente en Elara: ⟦0⟧ (⟦1⟧), ⟦2⟧; causa: ⟦3⟧ (⟦4⟧, ⟦5⟧). Relevante para decidir el destino de ⟦6⟧.": "Previous case in Elara: ⟦0⟧ (⟦1⟧), ⟦2⟧; cause: ⟦3⟧ (⟦4⟧, ⟦5⟧). Relevant when deciding the disposition of ⟦6⟧.",
  "Liberación o destino de cada lote: solo ⟦0⟧ o ⟦1⟧ (PNT-CAL-015).": "Release or destination for each lot: only ⟦0⟧ or ⟦1⟧ (PNT-CAL-015).",
  "9. Aprobaciones": "9. Approval",
  "Propuesto": "Proposed",
