  "Resultado": "Outcome",
  "Ejecución ⟦0⟧: ⟦1⟧ pasos automáticos y 1 aprobación, ⟦2⟧ llamadas (⟦3⟧ al modelo de lenguaje), coste estimado ⟦4⟧. Documento sujeto a la revisión de Calidad; no sustituye la decisión de destino del producto.": "Execution ⟦0⟧: ⟦1⟧ automatic steps and 1 approval, ⟦2⟧ calls (⟦3⟧ to the language model), cost estimated ⟦4⟧. Document subject to the quality review; does not replace the product's destination decision.",
