  "Revisión pendiente": "Review pending",
  "⟦0⟧ · revisión 1 · Documento generado por Prodigy el ⟦1⟧ · demostración con datos sintéticos · preparado por Ciklum": "⟦0⟧ · revision 1 · Document generated by Prodigy the ⟦1⟧ · demonstration with synthetic data · prepared by Ciklum",
  "No conformidad por excursión de temperatura en la cámara ⟦0⟧ · borrador para revisión": "Non-conformity per temperature excursion at cold room ⟦0⟧ · draft for review",
  "0 (borrador)": "0 (draft)",
  "Bloqueo asociado": "Hold partner",
  "Informe de incidencia": "Impact report",
  "Redactado por": "Brought by",
  "Disciplinas D1–D8": "Disciplines D1-D8",
  "Contenido": "Content",
  "Fecha objetivo": "Target date",
  "Aprobaciones": "Approval",
  "Redacción del borrador": "draft",
  "Redactado": "Redacted",
  "Aprobación y cierre": "Approval and closure",
  "Borrador generado a partir de las evidencias de la ejecución. Las fechas objetivo son una propuesta: las confirma el equipo del 8D. La causa raíz es una hipótesis hasta que Mantenimiento frigorífico la confirme.": "Draft generated from the evidence of execution. The target dates are a proposal: they are confirmed by the 8D team. The root cause is a hypothesis until Refrigeration Maintenance confirms it.",
  "⟦0⟧ · revisión 0 (borrador) · Documento generado por Prodigy el ⟦1⟧ · demostración con datos sintéticos · preparado por Ciklum": "⟦0⟧ · revision 0 (draft) · Document generated by Prodigy on ⟦1⟧ · demonstration with synthetic data · prepared by Ciklum",
  "Alarma de las ⟦0⟧ en la cámara ⟦1⟧: pico de ⟦2⟧ a las ⟦3⟧ y ⟦4⟧ min por encima de ⟦5⟧. La primera expedición afectada sale a las ⟦6⟧.": "Alarm of ⟦0⟧ in cold room ⟦1⟧: peak of ⟦2⟧ at ⟦3⟧ and ⟦4⟧ min above ⟦5⟧. The first affected dispatch leaves at ⟦6⟧.",
  "En esta sesión no se ha publicado el workflow, así que corre el de respaldo con los parámetros de PNT-CAL-012. La pantalla lo dice.": "No workflow has been published in this session, so the backup workflow uses the PNT-CAL-012 parameters. The screen makes that clear.",
  "Ejecutamos el workflow «⟦0⟧» que acabamos de publicar desde el procedimiento escrito: usa sus parámetros de verdad.": "We run the workflow \"⟦0⟧\" that we just published from the written procedure: it uses its parameters of truth.",
  "Cuatro agentes, cada uno con su sistema: Galileo para la temperatura; Easy WMS, SAP y Mapex para palés, lotes y expediciones; SAP QM para el bloqueo; Elara y Teams para la incidencia.": "Four agents, each using the relevant systems: Galileo for temperature; Easy WMS, SAP and Mapex for pallets, lots and shipments; SAP QM for the hold; Elara and Teams for the incident.",
  "Con los parámetros del workflow (más de ⟦0⟧ min por encima de ⟦1⟧), esta alarma no lo activa: ⟦2⟧ min. No se propone nada.": "With workflow parameters (more than ⟦0⟧ min above ⟦1⟧), this alarm does not activate it: ⟦2⟧ min. It's not proposed.",
  "Es la prueba de que el workflow usa sus parámetros de verdad.": "It's proof that the workflow uses its real parameters.",
  "Prodigy ha reunido la evidencia en ⟦0⟧ y propone bloquear ⟦1⟧ palés de ⟦2⟧ lotes y retener ⟦3⟧ expediciones.": "Prodigy has gathered the evidence in ⟦0⟧ and proposes place on hold ⟦1⟧ pallets of ⟦2⟧ lots and hold ⟦3⟧ shipments.",
  "Los ⟦0⟧ palés de los mismos lotes en silos quedan «a evaluar»: no estuvieron en ⟦1⟧. Todavía no se ha escrito nada en SAP QM ni en Easy WMS.": "The ⟦0⟧ pallets of the same lots silos are \"to be evaluated\": they were not in ⟦1⟧. Nothing has yet been written in SAP QM or Easy WMS.",
  "Se puede editar el alcance (quitar un lote, con motivo) o rechazar: si se rechaza, no se aplica nada y queda en auditoría.": "You can edit the scope (remove a lot, on the other hand) or refuse: if you refuse, nothing is applied and it remains in audit.",
  "Rechazado: no se ha bloqueado nada, ni en SAP QM ni en Easy WMS, y no hay no conformidad ni aviso. El motivo queda en el registro de auditoría.": "Rejected: nothing has been blocked in SAP QM or Easy WMS, and there is no non-conformity. The reason is left in the audit record.",
  "La decisión es siempre de Calidad; se puede volver a ejecutar cuando se quiera.": "The decision is always of Quality; it can be reexecuted whenever you want.",
  "Aprobado por ⟦0⟧. Ahora los agentes escriben: SAP QM, Easy WMS, Elara y Teams.": "Approved for ⟦0⟧. The agents now write: SAP QM, Easy WMS, Elara and Teams.",
  "Aplicado tras la aprobación: ⟦0⟧ en SAP QM, ⟦1⟧ palés inmovilizados y ⟦2⟧ expediciones retenidas en Easy WMS, ⟦3⟧ en Elara con el 8D en borrador y aviso por Teams.": "Implemented after approval: ⟦0⟧ in SAP QM, ⟦1⟧ pallets immobilized and ⟦2⟧ shipments held in Easy WMS, ⟦3⟧ in Elara with 8D in draft and advised by Teams.",
  "El informe de incidencia sale como documento controlado: código, revisión, aprobaciones y registro de la ejecución, listo para una auditoría IFS o BRCGS.": "The impact report is as a controlled document: code, review, approval and registration of implementation, ready for an IFS or BRCGS audit.",
  "Comparación ilustrativa: el tiempo de esta animación no mide rendimiento real. En el piloto se miden tiempos actuales y resultados con Prodigy.": "Illustrative comparison: the time of this animation does not measure real performance. The pilot's current times and results are measured with Prodigy.",
  "Pulsar «Ejecutar workflow» y comentar la sala de agentes mientras corre.": "Select “Run workflow” and talk through the agent activity as it runs.",
  "Pulsar «Aprobar bloqueo». Opcional: «Editar alcance» para enseñar el control.": "Press \"Approve hold.\" Optional: \"Edit scope\" to teach control.",
  "Esperar a que termine la fase de aplicación.": "Wait until the implementation phase is over.",
  "Abrir «Descargar informe de incidencia» y después ir a «Reclamación UKC-44718» (flecha derecha).": "Open \"Download incidence report\" and then go to \"Complaint UKC-44718\" (right arrow).",
  "«Volver a ejecutar el workflow» para aprobarlo, o pasar a la reclamación (flecha derecha).": "\"Rerun the workflow\" to approve it, or move to complaint (right arrow).",
  "Ir a «De palabras a workflow», dejar 15 min y volver a ejecutar.": "Go to \"From words to workflow,\" leave 15 min and run again.",
  "Comentar la sala de agentes mientras corre; se detendrá en la aprobación.": "Commenting the room of agents while running; it will stop at approval.",
