  "1. Aprobaciones": "1. Approval",
  "2. Objeto y alcance": "2. Subject matter and scope",
  "Respuesta de Congelados de Navarra (planta de Fustiñana) al ⟦0⟧ de ⟦1⟧, recibido de ⟦2⟧ el ⟦3⟧. Productos: ⟦4⟧. ⟦5⟧ preguntas en ⟦6⟧ bloques. Cada respuesta cita la fuente que la respalda y cada cita se ha comprobado literalmente en su fuente (⟦7⟧ de ⟦8⟧). Las preguntas sin evidencia suficiente en los procedimientos indexados no se responden y quedan para Calidad de planta.": "Response from Congelados de Navarra (plant of Fustiñana) to ⟦0⟧ of ⟦1⟧, received from ⟦2⟧ on ⟦3⟧. Products: ⟦4⟧. ⟦5⟧ questions in ⟦6⟧ blocks. Each response cites the source that supports it and each quote has been literally checked in its source (⟦7⟧ of ⟦8⟧). Questions without sufficient evidence in indexed procedures are not answered and remain for Plant Quality.",
  "3. Resumen de respuestas": "3. Summary of responses",
  "4. Respuestas": "4. Responses",
  "5. Fuentes consultadas": "5. Sources consulates",
  "Documentos indexados": "indexed documents",
