  "Descripción": "Description",
  "Respuesta a cuestionario técnico de proveedor": "Response to questionnaire supplier technician",
  "⟦0⟧ · ⟦1⟧ · recibido de ⟦2⟧": "⟦0⟧ · ⟦1⟧ · received from ⟦2⟧",
  "cuestionario-⟦0⟧": "questionnaire-⟦0⟧",
  "⟦0⟧ · vía ⟦1⟧": "⟦0⟧ · via ⟦1⟧",
  "Recibido": "Received",
  "Plazo de respuesta": "Response time",
  "Idioma de respuesta": "Language of response",
  "Inglés, con traducción de revisión": "English, with revision translation",
  "Documento generado por Prodigy · demostración con datos sintéticos · ⟦0⟧ · revisión ⟦1⟧": "Document generated by Prodigy · demonstration with synthetic data · ⟦0⟧ · revision ⟦1⟧",
  "Cada cliente de marca blanca trae su cuestionario técnico. En 2025 el grupo recibió ⟦0⟧ auditorías, visitas de cliente e inspecciones: ⟦1⟧ jornadas. Es trabajo de fondo que se come horas de Calidad.": "Each white-brand customer brings his questionnaire technician. In 2025 the group received ⟦0⟧ audits, customer visits and inspections: ⟦1⟧ days. It's background work that eats hours of Quality.",
  "Este llega de Freeworld Foods para el retailer del Reino Unido: ⟦0⟧ preguntas en inglés sobre el guisante 1 kg y el salteado de 600 g. Vuestros procedimientos están en español; da igual.": "It comes from Freeworld Foods for the UK retailer: ⟦0⟧ questions in English about pea 1 kg and the 600 g skipping. Your procedures are in Spanish; it doesn't matter.",
  "Al pulsar, Prodigy busca en procedimientos, fichas técnicas, certificaciones y en los registros de SAP, Mapex, Easy WMS, Opcenter y Elara, y redacta cada respuesta con su fuente.": "Prodigy searches procedures, product specifications, certifications and records in SAP, Mapex, Easy WMS, Opcenter and Elara, then drafts each answer with its supporting source.",
  "⟦0⟧ de ⟦1⟧ con borrador y cita; cada cita se comprueba contra el texto de la fuente. ⟦2⟧ quedan para Calidad: Listeria, residuos y clorato, y defensa alimentaria. Sin documento que lo respalde, no se inventa nada.": "⟦0⟧ of ⟦1⟧ with draft and quote; each quote is checked against the text of source. ⟦2⟧ remain for Quality: Listeria, waste and chlorate, and food defense. Without a supporting document, nothing is made up.",
  "B1: además de responder, avisa de que este mismo cliente tiene abierta la reclamación ⟦0⟧ por una piedra y de que la malla de DP-2 sigue pendiente. Hoy eso depende de que alguien se acuerde.": "B1: In addition to responding, notice that this same customer has open the complaint ⟦0⟧ by a stone and that the screen of DP-2 is still pending. Today that depends on someone remembering.",
  "C1: ⟦0⟧ palés del salteado para este cliente estaban en ⟦1⟧ durante la excursión de esta mañana. El cuestionario no vive aislado del resto de la planta.": "C1: ⟦0⟧ pallets for this client were at ⟦1⟧ during this morning's excursion. The questionnaire does not live isolated from the rest of the plant.",
  "C1: la respuesta cita el procedimiento de excursiones de temperatura.": "C1: the answer cites the procedure of temperature excursions.",
  "Nada sale sin aprobación: en bloque solo las de confianza alta; las de confianza media se revisan una a una.": "Nothing comes out without approval: in a block only those of high confidence; those of medium confidence are reviewed one by one.",
  "Revisión cerrada y registrada en la auditoría: cada aprobación, edición y asignación tiene hora y responsable.": "Closed and recorded audit: every approval, editing and assignment has time and responsibility.",
  "Excel para devolver el cuestionario al cliente y PDF como documento controlado: código, revisión, estado, aprobaciones y fuentes.": "Excel to return the questionnaire to the client and PDF as a controlled document: code, revision, status, approvals and sources.",
  "Comparativa del final: hoy, 2–4 horas repartidas en varios días (a validar en el piloto); aquí, el borrador en segundos más la revisión que acabamos de medir.": "Comparison of the end: today, 2-4 hours distributed in several days (to be validated in the pilot); here, the draft in seconds plus the review we have just measured.",
  "Pulsar «Preparar respuestas» y comentar el registro mientras se ejecuta.": "Select “Prepare answers” and talk through the execution log.",
  "Enseñar B1 (cita y aviso de la reclamación) y B4 (sin evidencia). Después «Aprobar las ⟦0⟧ de confianza alta», aprobar ⟦1⟧ una a una y «Asignar las ⟦2⟧ sin fuente a Calidad de planta».": "Teach B1 (quote and notice of complaint) and B4 (without evidence). After \"Approve the ⟦0⟧ of high confidence,\" approve ⟦1⟧ one to one and \"Assign the ⟦2⟧ without a source to Plant Quality.\"",
  "Pulsar «Descargar cuestionario (PDF)», enseñar la comparativa y pasar a «Procedimientos» con la flecha derecha.": "Press \"Download questionnaire (PDF),\" teach the comparison and move to \"Procedures\" with the right arrow.",
