  "¿Dónde se instala?": "Where is it deployed?",
  "En una máquina virtual de su CPD con Docker Compose o en Kubernetes con Helm, o en su suscripción de nube. No depende de servicios de Ciklum en la nube.": "In a virtual machine of your CPD with Docker Compose or in Kubernetes with Helm, or in your cloud subscription. It does not depend on services of Ciklum in the cloud.",
  "¿Cómo entran los usuarios?": "How do users sign in?",
  "Con SSO de Microsoft Entra ID (OIDC) o SAML 2.0. Los permisos van por rol y por realm (planta o departamento).": "With Microsoft SSO Enter ID (OIDC) or SAML 2.0. Permissions go by role and by realm (plant or department).",
  "¿Qué datos salen de nuestra red?": "What data leaves our network?",
  "Con un modelo local, la inferencia se ejecuta en su red. Con uno externo, se revisa el contenido enviado y el contrato. Los flujos de conectores, telemetría y enmascarado se validan con Sistemas.": "With a local model, the inference is run on your network. With an external one, the content sent and the contract are reviewed. The connectors, telemetry and masked flows are validated with Systems.",
  "¿Hay conectores de SAP, MES o SCADA?": "Are there SAP, MES or SCADA connectors?",
  "No de serie. En el piloto se construyen para 1–2 sistemas, por API o réplica de base de datos de solo lectura; la lectura de bases de datos Postgres ya funciona.": "Not serial. In the pilot are built for 1-2 systems, by API or database replica of only reading; the reading of Postgres databases is already working.",
  "¿Cuántos usuarios soporta?": "How many users can you support?",
  "La concurrencia se dimensiona y se verifica con pruebas de carga. Cada realm tiene límites de peticiones por minuto, de tokens al día y de presupuesto.": "Concurrent capacity is sized and verified through load testing. Each realm has request-per-minute, daily token and budget limits.",
  "¿En qué idioma trabaja?": "Which languages does it support?",
  "El chat y los agentes, en español; las respuestas al cliente, en su idioma. La consola de administración de Prodigy está en inglés.": "The chat and the agents, in Spanish; the answers to the customer, in their language. The Prodigy administration console is in English.",
  "¿Licencia y precio?": "Licensing and pricing?",
  "Se concretan en la propuesta comercial (SOW).": "They are reflected in the trade proposal (SOW).",
