  "No depende de servicios de Ciklum en la nube. Lo opera su equipo de Sistemas o un servicio gestionado.": "No Ciklum cloud service is required. Your IT team or a managed service operates the deployment.",
  "Modelo de lenguaje · ⟦0⟧": "Language model · ⟦0⟧",
  "⟦3⟧ Se cambia de modelo por configuración, sin tocar los workflows; también admite OpenAI o AWS Bedrock en la UE.": "⟦3⟧ It is changed from model to configuration, without touching workflows; it also supports OpenAI or AWS Bedrock in the EU.",
  "Acceso y permisos": "Access and permissions",
  "SSO con Microsoft Entra ID (OIDC) o SAML 2.0. Permisos por rol y por realm: el realm «Calidad · Fustiñana» solo ve sus procedimientos y sus datos.": "SSO with Microsoft Entra ID (OIDC) or SAML 2.0. Permissions by role and by realm: the realm \"Quality · Fustiñana\" only sees its procedures and data.",
  "La pasarela enmascara datos personales antes de llamar al modelo; los formatos DNI, NIE e IBAN se añaden en el piloto.": "The gateway masks personal data before calling the model; the DNI, NIE and IBAN formats are added to the pilot.",
  "Aprobación humana y auditoría": "Human approval and audit trail",
  "Bloquear en SAP QM, abrir una NC en Elara o enviar un correo al cliente requiere la aprobación de su responsable. Rechazar no aplica nada y queda registrado con el motivo.": "Placing stock on hold in SAP QM, opening a non-conformity in Elara or emailing a customer requires the responsible person's approval. Rejection applies no action and records the reason.",
