  "Ver el registro de esta sesión": "See the record of this session",
  "Fuera del alcance de Prodigy": "Outside Prodigy's scope",
  "No actúa sobre el control de planta: Galileo/SCADA solo se lee.": "It does not act on plant control: Galileo / SCADA is only read.",
  "No libera producto: lo decide el Responsable de Calidad (PNT-CAL-015).": "Product release is decided by the Quality Manager (PNT-CAL-015).",
  "No asigna tareas ni evalúa a personas: trabaja con lotes, equipos y documentos.": "It does not assign tasks or evaluate people: it works with lots, equipment and documents.",
  "Prodigy anota en cada petición los tokens, el modelo y el coste estimado en USD, y lo suma por realm, usuario, modelo y capacidad.": "Prodigy records tokens, model and estimated USD cost for each request, with totals by realm, user, model and capability.",
  "Presupuesto diario y mensual por realm, con aviso al ⟦0⟧; el bloqueo al superarlo es opcional. Es una estimación (tarifa × tokens) que se concilia con la factura del proveedor.": "Daily and monthly budgets per realm, with an alert at ⟦0⟧ and an optional block when exceeded. Costs are estimates (rate × tokens), reconciled against the provider's invoice.",
