  "Después del piloto: planificación de la recepción en campaña (medible en la campaña de guisante de 2027) o parte diario conectado al historian o al SCADA.": "After the pilot: campaign reception planning (measured in the campaign of pea of 2027) or daily report connected to the history or to SCADA.",
