  "dónde": "where",
  "A la vez en SAP QM (lote con bloqueo de calidad) y en Mecalux Easy WMS (palés inmovilizados y expediciones retenidas).": "At the same time, SAP QM (lot with quality hold) and Mecalux (pallets immobilised and shipments retained).",
  "Easy WMS no permite cargar un palé bloqueado.": "Easy WMS does not allow to load a blocked pallet.",
  "El registro incluye el motivo, el alcance (lotes, SSCC y ubicaciones), la referencia de origen y quién lo aprueba.": "The record includes the reason, the scope (lots, SSCC and locations), the reference of origin and who approves it.",
  "Producto ya expedido": "Product already dispatched",
  "¿Qué se hace si el producto afectado ya se ha expedido?": "What if the product concerned has already been dispatched?",
