  "Es de gravedad alta: cuerpos extraños duros o cortantes de 7 mm o más, aunque no haya lesión. Se informa en el día al Responsable de Calidad de planta.": "It is of high gravity: foreign bodies hard or cutting of 7 mm or more, even if there is no injury. It is reported in the day to Plant Quality Manager.",
  "Gravedad alta: cuerpos extraños duros o cortantes de 7 mm o más, aunque no haya lesión": "High severity: foreign bodies hard or cutting matter of 7 mm or more, even if there is no injury",
  "La investigación revisa como mínimo:": "The investigation reviews at least:",
  "La trazabilidad del lote hacia atrás (campo, recepción, línea y turno) y hacia delante (palés y expediciones).": "The traceability of the lot back (field, reception, line and shift) and forward (pallets and shipments).",
