  "En la respuesta al cliente, la causa se presenta como hipótesis hasta que haya evidencia.": "In the customer response, the cause is presented as a hypothesis until there is evidence.",
  "Una causa solo se comunica como confirmada cuando hay evidencia": "A cause only communicates as confirmed when there is evidence",
  "⟦0⟧: ⟦1⟧ de ⟦2⟧ mm en el lote ⟦3⟧ (L2, ⟦4⟧), gravedad alta según el apartado 3. La despedregadora DP-2 tiene abierta la ⟦5⟧ desde el ⟦6⟧⟦7⟧.": "⟦0⟧: ⟦1⟧ of ⟦2⟧ mm in lot ⟦3⟧ (L2, ⟦4⟧), high gravity as per paragraph 3. The destoner DP-2 has opened the ⟦5⟧ since the ⟦6⟧⟦7⟧.",
