  "Se verifica con probetas certificadas de Fe 2,0 mm, no férrico 2,5 mm y acero inoxidable 3,0 mm al inicio del turno, cada 2 h y al final de la producción.": "It is verified with test pieces certified Fe 2.0 mm, non-ferrous 2.5 mm and stainless steel 3.0 mm at the beginning of shift, every 2 h and at the end of production.",
  "Si una verificación falla o se superan las 2 h sin verificar, se retiene todo el producto envasado desde la última verificación correcta": "If a verification fails or exceeds 2 h without verification, all product packing is retained from the last correct verification",
  "El producto rechazado cae a un contenedor cerrado con llave que solo abre Calidad.": "The rejected product falls to a locked container that only opens Quality.",
  "Cada verificación se registra en la hoja de PCC de Elara, firmada por el operador y revisada por Calidad.": "Each verification is recorded on the CCP of Elara sheet, signed by the operator and reviewed by Quality.",
  "⟦0⟧ (línea ⟦1⟧) lleva ⟦2⟧ h sin verificar (máximo ⟦3⟧ h)⟦4⟧. Por el apartado 4 corresponde retener el producto envasado en ⟦5⟧ desde esa hora; la retención la aprueba Calidad (PNT-CAL-015).": "⟦0⟧ (line ⟦1⟧) has not been checked for ⟦2⟧ h (maximum ⟦3⟧ h)⟦4⟧. Section 4 requires a hold on product packed on ⟦5⟧ since that time; Quality approves the hold (PNT-CAL-015).",
