  "Cada selectora tiene una tasa de rechazo de referencia por producto, fijada en MES Mapex (1,5 % en guisante).": "Each selector has a reference rejection rate per product, fixed at MES Mapex (1.5% in pea).",
  "Por encima del 2,5 %, el operador revisa la entrada de producto y las barreras anteriores, en especial la despedregadora.": "Over 2.5%, the operator reviews the product entry and the previous barriers, in particular destoner.",
  "Por encima del 4 %, aviso inmediato a Calidad de turno y a Mantenimiento de línea, y muestreo reforzado de producto terminado.": "Above 4%, immediate notice to Quality of shift and Line Maintenance, and sampling reinforced finished product.",
  "⟦0⟧ (⟦1⟧) rechaza hoy el ⟦2⟧ (referencia ⟦3⟧), por encima del 4 %. La despedregadora DP-2, antes de ⟦4⟧ en la misma línea, tiene la malla pendiente de sustitución (⟦5⟧).": "⟦0⟧ (⟦1⟧) today rejects ⟦2⟧ (reference ⟦3⟧), above 4%. The destoner DP-2, before ⟦4⟧ on the same line, has the screen replacement slope (⟦5⟧).",
