  "Pregunta sobre los procedimientos de Calidad de Fustiñana": "Ask about Fustiñana's Quality procedures",
  "Cada frase de la respuesta cita el documento y el apartado de donde sale. Si ningún documento indexado lo recoge, la consulta lo indica y no responde.": "Each sentence of the answer quotes the document and the section from which it comes. If no indexed document collects it, the consultation indicates it and does not respond.",
