  "Con fuente": "Source available",
  "Las respuestas citan solo pasajes literales de los documentos vigentes indexados. Una pregunta sin fuente se responde «No hay evidencia suficiente en los procedimientos indexados», sin citas.": "The answers cite only verbatim passages of the indexed existing documents. A question without a source is answered \"There is not enough evidence in indexed procedures,\" without quotes.",
  "Consulta realizada": "Consultation",
  "Preguntar a los procedimientos": "Ask the procedures",
  "Consulta de los procedimientos de Calidad: la respuesta sale solo de los documentos controlados, y cada frase lleva su cita al documento y al apartado.": "Ask the Quality procedures: answers use the controlled documents, and each statement cites the document and section.",
  "Hay ocho documentos de Elara indexados: cadena de frío, bloqueo y liberación, reclamaciones y 8D, cuerpos extraños, Listeria, la instrucción de la despedregadora, una ficha técnica y la matriz de alérgenos. Aquí son sintéticos; en el piloto, los suyos vigentes.": "Eight Elara documents are indexed: cold chain, holds and release, complaints and 8D, foreign bodies, Listeria, the destoner work instruction, a product specification and the allergen matrix. Here they are synthetic; a pilot would use the customer’s current documents.",
  "Sirve en auditorías IFS o BRCGS, para formar a turnos nuevos y para contestar a clientes con la referencia exacta.": "This can support IFS or BRCGS audit preparation, training for new shifts and customer replies with exact references.",
  "Al pulsar una cita se abre el documento con el pasaje exacto resaltado. Y la respuesta se cruza con lo que pasa hoy en planta: la alarma de C-07, la reclamación UKC-44718 o el detector DM-1.": "When you press an citation the document is opened with the exact passage highlighted. And the answer is crossed with what happens today in the plant: the C-07 alarm, the complaint UKC-44718 or the DM-1 detector.",
  "Cuando no hay fuente lo dice y no inventa: ni respuesta ni cita. Si el tema está en un documento que no está indexado, lo nombra (PNT-CAL-018) y permite derivar la pregunta a Calidad.": "When there is no source he says it and does not invent: no answer or quote. If the subject is in a document that is not indexed, it is named (PNT-CAL-018) and allows the question to be referred to Quality.",
  "Pulsar «¿Qué hay que hacer si una cámara supera −18 °C?» y después la cita 1 para ver el pasaje resaltado.": "Select “What should we do if a cold room exceeds −18 °C?”, then citation 1 to highlight the source passage.",
  "Escribir una pregunta sin fuente, por ejemplo «¿Cada cuánto hacemos el simulacro de retirada?», y pulsar «Preguntar».": "Write a without a source question, for example, \"How much do we do the withdrawal drill?,\" and press \"Ask.\"",
  "Pasar a «Cómo encaja en CN» con la flecha derecha.": "Go to \"How it fits into CN\" with the right arrow.",
