  "Informe 8D en 5 días hábiles: antes del ⟦0⟧ · IT-MAN-DP-02 pide inspección reforzada de la malla hasta sustituirla": "8D report in 5 working days: before ⟦0⟧ · IT-MAN-DP-02 requests enhanced inspection of screen to replace it",
