  "Redacta la respuesta en inglés y su traducción de control": "Draws the answer in English and its translation of control",
  "Borrador listo: acuse de recibo, referencia ⟦0⟧, contención y fecha del informe · pendiente de aprobación": "Draft ready: acknowledgement of receipt, reference ⟦0⟧, containment and date of report · pending approval",
  "de": "of",
  "Estimado equipo de Calidad:": "Dear Quality Team:",
  "Hemos recibido una reclamación de un consumidor a través de nuestro cliente minorista del Reino Unido (gama de congelados de marca propia) sobre el producto indicado abajo, y necesitamos vuestro apoyo para investigarla con prioridad.": "We have received complaint from a consumer through our UK retail customer (range of brand-name frozen) on the product listed below, and we need your support to investigate it with priority.",
  "Producto: ⟦0⟧ (marca propia del minorista)": "Product: ⟦0⟧ (retail brand)",
  "Código de lote: ⟦0⟧": "Code lot: ⟦0⟧",
  "Consumo preferente: ⟦0⟧": "Best before: ⟦0⟧",
  "Referencia del consumidor: ⟦0⟧": "Consumer reference: ⟦0⟧",
  "Reclamación recibida por el minorista: ⟦0⟧": "Complaint received by the retailer: ⟦0⟧",
  "El consumidor indica que, al servir el producto, encontró un cuerpo extraño pequeño y duro que parece una piedra de unos ⟦0⟧ mm. No se han comunicado lesiones. El consumidor conserva el objeto y el minorista ha compartido dos fotografías (adjuntas). La muestra física está de camino a nuestra oficina del Reino Unido y os la enviaremos en cuanto la recibamos.": "The consumer indicates that, by serving the product, he found a small and hard foreign body that looks like a stone of about ⟦0⟧ mm. No injuries have been reported. The consumer retains the object and the retailer has shared two photographs (attached). The physical sample is on its way to our UK office and we will send it to you as soon as we receive it.",
  "Al tratarse de una reclamación por contaminación física en un producto de marca propia del minorista, nuestro cliente pide un informe de investigación completo en un plazo de 5 días hábiles, que incluya:": "As it is complaint for physical pollution in a product of the retailer's own brand, our client requests a full research report within 5 working days, including:",
  "- la trazabilidad del lote (materia prima, cosecha, recepción y línea de proceso);": "- traceability of lot (raw material, harvest, reception and process line);",
  "- los controles de eliminación de piedras y de cuerpos extraños de la línea (despedregadora, selección óptica) y sus registros de la fecha de producción;": "- the stone removal controls and foreign bodies of the line (destoner, optical selection) and their records of the date of production;",
  "- la causa raíz y las acciones correctivas y preventivas;": "- root cause and corrective and preventive actions;",
  "- la confirmación de si hay otro stock del mismo lote afectado.": "- confirmation of whether there is another stock of the same lot affected.",
  "Os pedimos que confirméis la recepción y nos indiquéis vuestra referencia de investigación.": "We ask you to confirm the reception and indicate your research reference to us.",
  "Un saludo,": "A greeting,",
  "Equipo de Quality Assurance": "Quality Assurance Team",
  "⟦0⟧ el ⟦1⟧": "⟦0⟧ on ⟦1⟧",
  "con guisante cosechado y recibido el mismo día (agricultor ⟦0⟧, recepción ⟦1⟧)": "with pea harvested and received on the same day (farmer ⟦0⟧, reception ⟦1⟧)",
  "con guisante cosechado el ⟦0⟧ y recibido el ⟦1⟧ (agricultor ⟦2⟧, recepción ⟦3⟧)": "with pea harvested on ⟦0⟧ and received ⟦1⟧ (farmer ⟦2⟧, reception ⟦3⟧)",
  "Estimado equipo de Quality Assurance:": "Dear Quality Assurance team:",
  "Gracias por su correo del ⟦0⟧. Confirmamos la recepción de la reclamación del consumidor ⟦1⟧ (cuerpo extraño: una piedra de unos ⟦2⟧ mm) sobre ⟦3⟧, lote ⟦4⟧, consumo preferente ⟦5⟧. Lamentamos la preocupación causada al consumidor y tomamos nota de que no se han comunicado lesiones.": "Thank you for your ⟦0⟧ mail. We confirm the reception of the complaint consumer ⟦1⟧ (foreign body: a stone of about ⟦2⟧ mm) over ⟦3⟧, lot ⟦4⟧, best before ⟦5⟧. We regret the concern of the consumer and note that no injuries have been reported.",
  "Nuestra referencia de investigación es ⟦0⟧. La reclamación se gestiona según nuestro procedimiento de reclamaciones de cliente y se documentará en un informe 8D.": "Our research reference is ⟦0⟧. The complaint is managed according to our customer's complaints procedure and will be documented in a 8D report.",
  "Primeros datos de nuestros registros:": "First data from our records:",
  "- Trazabilidad: el lote se fabricó en nuestra planta de Fustiñana el ⟦0⟧ (línea ⟦1⟧, turno de ⟦2⟧) ⟦3⟧.": "- Traceability: lot was manufactured on our plant of Fustiñana ⟦0⟧ (line ⟦1⟧, shift of ⟦2⟧) ⟦3⟧.",
  "- Distribución: se fabricaron ⟦0⟧ palés (⟦1⟧). ⟦2⟧ palés se expidieron a Freeworld Foods Ltd (⟦3⟧). Los ⟦4⟧ palés que quedan en nuestro almacén se han retenido por Calidad.": "- Distribution: ⟦0⟧ pallets (⟦1⟧) were manufactured. ⟦2⟧ pallets were issued to Freeworld Foods Ltd (⟦3⟧). The ⟦4⟧ pallets left in our warehouse have been on hold by Quality.",
  "- Controles de cuerpos extraños: estamos revisando los registros de la despedregadora y de la selección óptica de la fecha de producción, junto con los registros de mantenimiento de la línea ⟦0⟧.": "- foreign bodies controls: we are reviewing the records of the destoner and the optical selection of the date of production, together with the maintenance records of the line ⟦0⟧.",
  "Próximos pasos:": "Next steps:",
  "- Examinaremos la muestra física en cuanto llegue. Les rogamos que la envíen a la atención de nuestro departamento de Calidad en Fustiñana, indicando ⟦0⟧.": "- We'll examine the physical sample as soon as it gets here. We ask you to send it to the attention of our Quality Department in Fustiñana, indicating ⟦0⟧.",
  "- Les enviaremos el informe de investigación, con la causa raíz y las acciones correctivas y preventivas, a más tardar el ⟦0⟧.": "- We will send you the research report, with the root cause and the corrective and preventive actions, no later than ⟦0⟧.",
  "- Para confirmar si hay otro stock afectado, ¿pueden indicarnos la cantidad del lote ⟦0⟧ que conservan Freeworld Foods y el minorista?": "- To confirm if there is another stock affected, can you tell us the amount of lot ⟦0⟧ that they retain Freeworld Foods and the retailer?",
  "Departamento de Calidad": "Quality Department",
  "Congelados de Navarra · planta de Fustiñana": "Congelados de Navarra · plant of Fustiñana",
  "Aplicada": "Implemented",
  "No aplicada": "Not implemented",
