  "⟦0⟧: investigación y contacto con el cliente": "⟦0⟧: research and contact with the customer",
  "⟦0⟧: DP-2 y OPT-2 (línea ⟦1⟧)": "⟦0⟧: DP-2 and OPT-2 (line ⟦1⟧)",
  "⟦0⟧: materia prima de ⟦1⟧": "⟦0⟧: raw material of ⟦1⟧",
  "⟦0⟧: stock en ⟦1⟧ y expediciones": "⟦0⟧: stock in ⟦1⟧ and shipments",
  "Contacto externo: ⟦0⟧.": "External contact: ⟦0⟧.",
  "Un consumidor del Reino Unido encontró una ⟦0⟧ de unos ⟦1⟧ mm al servir ⟦2⟧ (marca blanca de un retailer, vía Freeworld Foods Ltd). Sin lesiones.": "A UK consumer found a ⟦0⟧ of about ⟦1⟧ mm while serving ⟦2⟧ (a retailer's private-label product, through Freeworld Foods Ltd). No injuries were reported.",
  "Lote ⟦0⟧, consumo preferente ⟦1⟧, fabricado el ⟦2⟧ en ⟦3⟧, turno de ⟦4⟧: ⟦5⟧ palés, ⟦6⟧": "Lot ⟦0⟧, best before ⟦1⟧, manufactured ⟦2⟧ in ⟦3⟧, shift of ⟦4⟧: ⟦5⟧ pallets, ⟦6⟧",
