  "Cuerpo extraño (⟦0⟧ de unos ⟦1⟧ mm) en ⟦2⟧ · lote ⟦3⟧ · ⟦4⟧, ⟦5⟧": "Foreign body (⟦0⟧ of about ⟦1⟧ mm) in ⟦2⟧ · lot ⟦3⟧ · ⟦4⟧, ⟦5⟧",
  "Documento controlado · vista previa": "Document controlled · preview",
  "Informe al cliente": "Customer information",
  "antes del ⟦0⟧": "before ⟦0⟧",
  "Reclamación de ⟦0⟧ por un retailer del Reino Unido (marca blanca): ⟦1⟧ de unos ⟦2⟧ mm en ⟦3⟧, lote ⟦4⟧. Sin lesiones. El lote se fabricó el ⟦5⟧ en ⟦6⟧; ⟦7⟧ de sus ⟦8⟧ palés están expedidos y ⟦9⟧ siguen en ⟦10⟧.": "Complaint of ⟦0⟧ by a UK retailer (private label): ⟦1⟧ of about ⟦2⟧ mm in ⟦3⟧, lot ⟦4⟧. No injuries. The lot was manufactured in ⟦5⟧ in ⟦6⟧; ⟦7⟧ of its ⟦8⟧ pallets are dispatched and ⟦9⟧ remain in ⟦10⟧.",
  "Hipótesis de causa, pendiente de confirmar con la muestra: desgaste de la malla de la despedregadora DP-2 (⟦0⟧, abierta desde el ⟦1⟧).": "Case scenario, to be confirmed with the sample: wear of screen of destoner DP-2 (⟦0⟧, open from ⟦1⟧).",
  "Causa pendiente de la muestra.": "Case pending from the sample.",
  "Anexo A · Traza del lote": "Annex A · Trace of lot",
  "Anexo B · Palés del lote (⟦0⟧ SSCC)": "Annex B · Pallets of lot (⟦0⟧ SSCC)",
  "Anexo C · Reclamaciones anteriores (12 meses)": "Annex C · previous Complaints (12 months)",
  "Aprobado el ⟦0⟧": "Approved on ⟦0⟧",
  "Rechazado el ⟦0⟧": "Rejected ⟦0⟧",
  "Confirmación de causa (D4) y cierre (D8) · pendiente": "Confirmation of cause (D4) and closure (D8) · pending",
  "Documento generado por Prodigy el ⟦0⟧ · demostración con datos sintéticos · preparado por Ciklum": "Document generated by Prodigy on ⟦0⟧ · demonstration with synthetic data · prepared by Ciklum",
  "Correo de Freeworld Foods, la filial de Congelados de Navarra en el Reino Unido, por un retailer de marca blanca: una piedra de unos ⟦0⟧ mm en guisante de 1 kg. Llegó el sábado ⟦1⟧ a las ⟦2⟧, en inglés y con plazo.": "Freeworld Foods mail, the subsidiary of Congelados de Navarra in the United Kingdom, for a white-brand retailer: a stone of about ⟦0⟧ mm in pea of 1 kg. He arrived on Saturday ⟦1⟧ at ⟦2⟧, in English and with a deadline.",
  "En producción, Prodigy lo analiza en cuanto entra en el buzón de Calidad. Aquí lo lanzamos a mano para ver qué hace y qué sistemas consulta.": "In production, Prodigy would analyse the email as it arrives in the Quality inbox. Here we start it manually to show the steps and systems involved.",
  "Aprobada: respuesta enviada, ⟦0⟧ palés retenidos en ⟦1⟧ y la ⟦2⟧ en curso en Elara. Todo queda en el registro de auditoría.": "Adopted: response sent, ⟦0⟧ pallets retained in ⟦1⟧ and ⟦2⟧ ongoing in Elara. Everything is left in the audit record.",
  "La comparación de abajo: hoy, 3–4 personas y 6 sistemas durante horas; aquí, una revisión y una aprobación. La cifra de «hoy» la medimos en el piloto, no la inventamos.": "The comparison below: today, 3-4 people and 6 systems for hours; here, a review and a approval. The figure of \"today\" we measured it in the pilot, we didn't invent it.",
  "El informe 8D se descarga como documento controlado: código, revisión, estado, aprobaciones y número de página.": "The 8D report is downloaded as a controlled document: code, revision, status, approvals and page number.",
  "Rechazada: no se ha enviado nada ni se ha retenido ningún palé. El motivo queda en auditoría.": "Rejected: nothing has been sent and no on hold has been sent. The reason is still under audit.",
  "Se puede preparar otra versión, editarla y volver a aprobar.": "Another version can be prepared, edited and returned to approve.",
  "Lo resaltado en el correo es lo que Prodigy ha extraído. Cada dato se comprueba en SAP: el lote existe y el producto coincide.": "What was highlighted in the mail is what Prodigy has extracted. Each data is checked in SAP: the lot exists and the product matches.",
  "La traza: cosecha del ⟦0⟧ de ⟦1⟧, recepción ⟦2⟧ a las ⟦3⟧ y línea ⟦4⟧. ⟦5⟧ palés ya están en el Reino Unido y ⟦6⟧ siguen en ⟦7⟧.": "The trace: harvest of ⟦0⟧ of ⟦1⟧, reception ⟦2⟧ at ⟦3⟧ and line ⟦4⟧. ⟦5⟧ pallets are already in the United Kingdom and ⟦6⟧ are still in ⟦7⟧.",
  "El dato que cambia la investigación: la malla de DP-2 tenía una orden abierta desde el ⟦0⟧, un día antes de fabricar el lote. Es una hipótesis, no la causa: la confirma Calidad con la muestra.": "The data that changes the investigation: the screen of DP-2 had an open order since ⟦0⟧, one day before making the lot. It is a hypothesis, not the cause: it confirms Quality with the sample.",
  "Histórico: en noviembre de 2025 hubo una piedra en espinaca con una causa del mismo tipo en Alcorioja (⟦0⟧). El 8D lo recoge en la prevención (D7).": "Historical: In November 2025 there was a stone in spinach with a cause of the same type in Alcorioja (⟦0⟧). The 8D is collected in prevention (D7).",
  "Sin reclamaciones parecidas en el histórico.": "Without complaints similar in the historical.",
  "La respuesta en inglés confirma hechos y fechas y no adelanta la causa. No sale hasta que Calidad la aprueba.": "The English answer confirms facts and dates and does not advance the case. It doesn't come out until Quality approves.",
  "Pulsar «Analizar reclamación» y leer en voz alta dos líneas del registro: el sistema consultado y lo que encuentra.": "Select “Analyse complaint” and read two log entries aloud: the system consulted and what it found.",
  "Pulsar «Descargar informe 8D» y enseñar la cabecera del documento. Después, pasar a «Procedimientos» en la barra lateral.": "Click \"Download 8D report\" and show the document header. Then move to \"Procedures\" on the side bar.",
  "Pulsar «Preparar nueva versión» y después «Aprobar y enviar».": "Press \"Prepare new version\" and then \"Approve and send.\"",
  "Pulsar «Revisar y aprobar» (arriba) o bajar hasta la respuesta y pulsar «Aprobar y enviar». Opcional: «Corregir» el lote con uno inexistente para enseñar que no inventa datos.": "Press \"Check and approve\" (above) or lower to the answer and press \"Approve and send.\" Optional: \"Correct\" the lot with a non-existent to teach that it does not invent data.",
  "No se muestra traza ni se prepara el 8D: Prodigy no genera datos que no estén en los sistemas.": "trace is not shown and 8D is not prepared: Prodigy does not generate data that is not in the systems.",
