  "Les comunicamos la retirada del siguiente producto suministrado por Congelados de Navarra:": "We tell you the withdrawal of the following product supplied by Congelados de Navarra:",
  "Lote: ⟦0⟧ · consumo preferente ⟦1⟧": "Lot: ⟦0⟧ · Best before ⟦1⟧",
  "Entregado: ⟦0⟧ del ⟦1⟧ · ⟦2⟧ (⟦3⟧)": "Delivery: ⟦0⟧ of ⟦1⟧ · ⟦2⟧ (⟦3⟧)",
  "Les pedimos que inmovilicen de inmediato las unidades de este lote en sus almacenes y puntos de venta y que nos confirmen, respondiendo a este correo, las cantidades localizadas. Nuestro equipo de Calidad les contactará para organizar la recogida.": "We ask you to immediately immobilize the units of this lot in your stores and points of sale and to confirm, in response to this mail, the quantities located. Our Quality team will contact you to organize the collection.",
  "La entrega prevista para ⟦0⟧ (⟦1⟧, ⟦2⟧ de ⟦3⟧, lote ⟦4⟧) queda retenida en nuestras instalaciones. Les confirmaremos la nueva fecha de entrega.": "The planned delivery for ⟦0⟧ (⟦1⟧, ⟦2⟧ of ⟦3⟧, lot ⟦4⟧) is held in our facilities. We'll confirm the new delivery date.",
  "Motivo: simulacro anual de retirada (IFS Food y BRCGS). En una retirada real, aquí se indican el peligro y el destino del producto.": "Reason: annual simulation of withdrawal (IFS Food and BRCGS). In a real withdrawal, the danger and destination of the product are indicated here.",
  "Atentamente, Calidad · Congelados de Navarra Planta de Fustiñana": "Sincerely, Quality · Congelados de Navarra Plant of Fustiñana",
  "Kind regards, Quality Department · Congelados de Navarra Fustiñana plant": "Kind regulations, Quality Department · Congelados de Navarra Fustiñana plant",
