  "Objetivo ilustrativo: trazabilidad en 4 horas. Confirmar alcance, periodicidad y plazos con Calidad y la edición aplicable.": "Illustrative objective: traceability in 4 hours. Confirm scope, periodicity and deadlines with Quality and the applicable edition.",
