  "Simulacro de retirada con punto de partida en ⟦0⟧ ⟦1⟧ (⟦2⟧). Se comprueba la trazabilidad hacia atrás (recepción, agricultor y parcela) y hacia delante (palés por SSCC, expediciones y clientes), con balance de masas. El ejercicio no bloquea stock ni envía avisos.": "withdrawal simulation with starting point at ⟦0⟧ ⟦1⟧ (⟦2⟧). The traceability is checked back (reception, farmer and plot) and forward (pallets for SSCC, shipments and customers), with mass balance. The exercise does not block stock or send warnings.",
