  "9. Decisión y conclusión": "9. Decision and conclusion",
  "⟦0⟧ Conclusión: la información necesaria para una retirada se obtiene completa y cuadra en kilos. Acciones de mejora propuestas: verificar los contactos de retirada de cada cliente y revisar la merma de «bajo calibre» de la línea L2 con Producción.": "⟦0⟧ Conclusion: the information required for a withdrawal is obtained complete and square in kilos. Proposed improvement actions: verify contacts of withdrawal for each client and review the loss \"low calibre\" line L2 with Production.",
  "Simulacro: no se ha bloqueado stock en SAP QM ni en Mecalux Easy WMS y no se ha enviado ningún aviso a clientes. Datos sintéticos de demostración.": "Simulacro: no stock has been blocked in SAP QM or Mecalux Easy WMS and no notice has been sent to customers. Synthetic data of demonstration.",
