  "sin decisión": "without a decision",
  "Simulacro de retirada con traza y balance de masas; en el piloto Calidad confirma el protocolo de auditoría y medimos el tiempo real.": "A mock withdrawal with traceability and mass balance. In the pilot, Quality confirms the audit protocol and we measure actual elapsed time.",
  "Se elige el punto de partida: un lote, todos los lotes de una parcela o un granel de campaña.": "Choose the starting point: one lot, every lot from a field, or a bulk campaign batch.",
  "Prodigy recorre SAP, Mapex y Easy WMS hacia atrás hasta la parcela y hacia delante hasta cada SSCC, expedición y cliente, y cuadra el balance en kilos.": "Prodigy follows SAP, Mapex and Easy WMS records backwards to the field and forwards to each SSCC, shipment and customer, then reconciles the mass balance in kilograms.",
  "Trazado simulado en ⟦0⟧; el objetivo de 4 horas es ilustrativo y lo confirma Calidad.": "Traced simulated in ⟦0⟧; the 4-hour target is illustrative and confirmed by Quality.",
  "El balance cuadra en kilos: ⟦0⟧ conciliado, con cada merma justificada por su etapa en Mapex. Lo que no cuadra (⟦1⟧) se ve, no se reparte.": "The balance is in kilos: ⟦0⟧ reconciled, with every loss justified by its stage in Mapex. What doesn't fit (⟦1⟧) is seen, not distributed.",
  "Lo accionable: ⟦0⟧ se retendría, y el stock del mismo origen se bloquearía.": "The variable: ⟦0⟧ would be retained, and the stock of the same origin would be blocked.",
  "Los avisos se preparan en el idioma de cada cliente, pero en un simulacro no se envía nada. Decide Calidad.": "The notifications are prepared in the language of each client, but in a drill nothing is sent. Decide Quality.",
  "El registro sale con código, revisión, tiempos de cada actividad y bloque de firmas, como los registros de su sistema de calidad.": "The record comes out with code, review, times of each activity and signature block, such as your quality system records.",
  "Pulsar «Iniciar simulacro» con el lote L26-261-FUS-GUI-03 (o elegir «Parcela P-0412-07»).": "Select “Start exercise” with lot L26-261-FUS-GUI-03, or choose field P-0412-07.",
  "Pulsar «Ver aviso» del cliente y después «Aprobar y cerrar simulacro».": "Press \"See Customer Warning\" and then \"Approve and close simulacro.\"",
  "«Descargar paquete de retirada»: CSV de SSCC y registro imprimible. Después, «Cuestionario de cliente» (flecha derecha).": "\"Download withdrawal package\": CSV SSCC and printable record. Then, \"Questionnaire customer\" (right arrow).",
