  "Verificar DM-1 con probetas ahora (⟦0⟧ h sin verificar; máximo ⟦1⟧ h). Calidad decide la retención del producto envasado desde las ⟦2⟧ (PNT-CAL-031).": "Check DM-1 with test pieces now (⟦0⟧ h unverified; maximum ⟦1⟧ h). Quality decides hold of product packing from ⟦2⟧ (PNT-CAL-031).",
  "Inspeccionar el compresor: ⟦0⟧ mm/s RMS (referencia ⟦1⟧). Valorar el relevo con NH3-C1, que está en rango.": "Inspect compressor: ⟦0⟧ mm / s RMS (reference ⟦1⟧). To value the relief with NH3-C1, which is in range.",
  "Agua de escaldado a ⟦0⟧ (consigna ⟦1⟧): revisar el aporte de vapor y verificar con ensayo de peroxidasa. La caldera CAL-B1 está en rango (⟦2⟧ bar), así que la causa probable es local.": "Blanching water at ⟦0⟧ (setpoint ⟦1⟧): check steam supply and verify with a peroxidase test. Boiler CAL-B1 is within range (⟦2⟧ bar), so the likely cause is local.",
  "Aire del túnel a ⟦0⟧ (consigna ⟦1⟧): revisar desescarche y carga antes de la entrada de maíz de fin de campaña del ⟦2⟧.": "Tunnel air at ⟦0⟧ (setpoint ⟦1⟧): review defrost and load before entry of ⟦2⟧ end of year maize.",
  "Programar el desescarche de EV-SIL3 (⟦0⟧ h desde el último).⟦1⟧": "Schedule defrost of EV-SIL3 (⟦0⟧ h from last) .⟦1⟧",
