  "⟦0⟧ (L2) rechaza el ⟦1⟧ de producto (referencia ⟦2⟧) y la malla de la despedregadora DP-2 sigue pendiente de repuesto: ⟦3⟧, abierta desde el ⟦4⟧ (⟦5⟧ días). La reclamación ⟦6⟧ (piedra de ⟦7⟧ mm) es del lote ⟦8⟧, procesado en L2 el ⟦9⟧, un día después de anotarse el desgaste.": "⟦0⟧ (L2) rejects ⟦1⟧ product (reference ⟦2⟧) and screen of the destoner DP-2 remains outstanding: ⟦3⟧, open from ⟦4⟧ (⟦5⟧ days). The complaint ⟦6⟧ (⟦7⟧ mm stone) is lot ⟦8⟧, processed in L2 on ⟦9⟧, one day after the wear is recorded.",
