  "Actuación sobre el control de planta": "Action on plant control",
  "El texto pide cambiar consignas o arrancar y parar equipos. Prodigy lee Galileo/SCADA y Mapex, pero no escribe en el control de planta: esos cambios los hace el personal de planta desde su sistema.": "The text requests setpoint changes or starting/stopping equipment. Prodigy reads Galileo/SCADA and Mapex but does not update plant controls. Plant staff make those changes in their own system.",
