  "Escribe un número.": "Write a number.",
  "Debe estar entre ⟦0⟧ y ⟦1⟧ ⟦2⟧.": "It must be between ⟦0⟧ and ⟦1⟧ ⟦2⟧.",
  "Debe quedar por debajo de la excursión crítica (⟦0⟧).": "It must be below the critical excursion (⟦0⟧).",
