  "⟦0⟧ · ⟦1⟧: de ⟦2⟧ a ⟦3⟧": "⟦0⟧ · ⟦1⟧: from ⟦2⟧ to ⟦3⟧",
  "Prueba de activación": "Activation test",
  "De palabras a workflow": "From words to workflow",
  "Si el texto pide algo fuera de su alcance, Prodigy no se inventa un workflow: explica por qué y no guarda nada.": "If the text asks for something out of its reach, Prodigy does not invent a workflow: it explains why and does not save anything.",
  "Solo encadena agentes habilitados en el espacio de Calidad; la petición queda igualmente en auditoría.": "Only agents are enabled in the Quality space; the request is also under audit.",
  "Publicado como ⟦0⟧ y registrado en auditoría: quién, cuándo y qué versión.": "Published as ⟦0⟧ and recorded in audit: who, when and what version.",
  "Desde ahora, una alarma de temperatura de Galileo/SCADA lo dispara sola. Lo vemos con la alarma real de esta mañana: ⟦0⟧, ⟦1⟧.": "From now on, a temperature alarm of Galileo / SCADA shoots it alone. We see it with the real alarm this morning: ⟦0⟧, ⟦1⟧.",
  "Desde ahora se ejecuta solo cuando se cumple el disparador.": "From now on it runs only when trigger is completed.",
  "Si mañana Calidad cambia el procedimiento, se edita el texto o un parámetro y se publica la v2: la anterior queda en el historial.": "If tomorrow Quality changes the procedure, the text or a parameter is edited and the v2 is published: the previous one is in the history.",
  "Cada frase está enlazada con lo que ha entendido: el disparador sale de «supere ⟦0⟧ durante más de ⟦1⟧ minutos».": "Each sentence is linked to what you have understood: the trigger comes out of \"over ⟦0⟧ for more than ⟦1⟧ minutes.\"",
  "Cada frase del texto está enlazada con lo que ha entendido: disparador, pasos y aprobación.": "Each sentence of the text is linked to what you have understood: trigger, steps and approval.",
  "Cada paso dice qué sistema toca: Galileo para la temperatura; SAP, Mapex y Easy WMS para palés y lotes; SAP QM para el bloqueo; Elara y Teams para la incidencia.": "Each step says which system touches: Galileo for temperature; SAP, Mapex and Easy WMS for pallets and lots; SAP QM for hold; Elara and Teams for incidence.",
  "Cada paso dice qué agente lo hace y qué sistema toca.": "Each step says what agent does and what system it plays.",
  "El bloqueo no se aplica sin la aprobación de Calidad: lo exige PNT-CAL-015 y el workflow lo respeta aunque el texto no lo dijera.": "The hold does not apply without the approval Quality: it is required by PNT-CAL-015 and the workflow respects it even if the text did not say so.",
  "Los parámetros se ajustan aquí y se contrastan con el procedimiento. Si preguntan por los límites: escribir «Compra acciones de una eléctrica cuando baje la luz» y pulsar «Crear workflow».": "The parameters are adjusted here and contrasted with the procedure. If you ask about the limits: write \"Buy shares of an electric when the light comes down\" and press \"Create workflow.\"",
  "Así escribe Calidad un procedimiento: en castellano, como en su PNT. No hay que dibujar ni programar nada.": "Quality writes the procedure in everyday language, just as in an SOP. There is no diagram to draw and no code to write.",
  "Prodigy lo convierte en un workflow de la plataforma: disparador, agentes en orden, aprobación humana y salidas, cada uno enlazado a su frase.": "Prodigy turns it into a workflow: a trigger, agents in sequence, human approval and outputs, each linked to its source sentence.",
  "Honestidad: el generador desde texto se simula aquí y su integración en Prodigy se valida en el piloto; los workflows (Routines), el editor, la aprobación y la auditoría son de serie.": "The text-to-workflow generator is simulated here; its integration into Prodigy will be validated in the pilot. Routines, the editor, approval and auditing are existing framework capabilities.",
  "Pulsar «Restaurar plantilla» y crear el workflow de cadena de frío.": "Press \"Restore template\" and create the workflow of cold chain.",
  "Pulsar «⟦0⟧».": "Press \"⟦0⟧.\"",
  "Pasar a la siguiente escena con la flecha derecha.": "Go to the next scene with the right arrow.",
  "Señalar una frase resaltada y su paso en el diagrama; después, «Publicar workflow».": "To point out a highlighted phrase and its step in the diagram; then, \"Publish workflow.\"",
  "Pulsar «Crear workflow» con el texto de cadena de frío.": "Select “Create workflow” using the cold-chain example.",
