  "Respuestas desde los documentos vigentes, con la cita de cada frase": "Answers from current documents, with a source citation for each statement",
  "Cada frase de la respuesta cita el documento y el apartado del que sale. Si ningún documento indexado lo recoge, la consulta lo indica y no responde.": "Each statement cites its source document and section. If the indexed documents do not contain the answer, Prodigy says so.",
  "Pulsa el número de una cita de la respuesta o un documento de la biblioteca: se abre aquí con el pasaje exacto resaltado.": "Select a citation number in an answer, or a document in the library, to see the exact source passage highlighted here.",
  "Bloqueo y liberación de producto (hold de calidad)": "Product hold and release",
  "Prodigy lee de sus sistemas y prepara propuestas con sus procedimientos; antes de escribir en un sistema, una persona aprueba.": "Prodigy reads your systems and prepares proposals using your procedures. A person approves each proposal before any system is updated.",
  "Ejercicio de trazabilidad y retirada para simulacros IFS Food y BRCGS: genealogía atrás y adelante, balance de masas y clientes a avisar, a partir de un lote, una parcela o un granel.": "A traceability and withdrawal exercise for IFS Food and BRCGS scenarios: backward and forward genealogy, mass balance and customers to notify, starting from a lot, field or bulk batch.",
  "El ejercicio muestra la trazabilidad hacia atrás y hacia delante, con balance de masas. Calidad valida el protocolo aplicable.": "The exercise shows backward and forward traceability with mass balance. Quality validates the applicable protocol.",
  "pasos y sistemas": "steps and systems",
  "El plano de Fustiñana resume la planta de un vistazo: gris lo normal, color lo que pide atención. C-07 late en rojo; al pulsarla se ven sus palés en los silos y los muelles de las expediciones afectadas.": "The Fustiñana map gives a plant overview: grey means normal; colour highlights what needs attention. C-07 pulses red. Select it to see the pallets in the silos and the bays for affected shipments.",
  "Tres asuntos: la alarma de C-07 de las 05:50 (38 palés; la primera expedición sale a las 09:30), la reclamación UKC-44718 del Reino Unido y el parte con 4 críticos, uno de ellos un PCC.": "Three priorities: the 05:50 alarm in C-07 (38 pallets; the first shipment leaves at 09:30), UK complaint UKC-44718, and the daily report with 4 critical alerts, including one CCP.",
  "Alarma de las 05:50 en la cámara C-07: pico de −13,9 °C a las 06:25 y 50 min por encima de −18 °C. La primera expedición afectada sale a las 09:30.": "At 05:50, cold room C-07 triggered an alarm: a peak of −13.9 °C at 06:25 and 50 minutes above −18 °C. The first affected shipment leaves at 09:30.",
  "Correo de Freeworld Foods, la filial de Congelados de Navarra en el Reino Unido, por un retailer de marca blanca: una piedra de unos 8 mm en guisante de 1 kg. Llegó el sábado 26/09 a las 10:14, en inglés y con plazo.": "An email from Freeworld Foods, Congelados de Navarra’s UK subsidiary, on behalf of a private-label retailer: an approximately 8 mm stone in a 1 kg bag of peas. It arrived on Saturday 26/09 at 10:14, in English, with a deadline.",
  "Cada cliente de marca blanca trae su cuestionario técnico. En 2025 el grupo recibió 108 auditorías, visitas de cliente e inspecciones: 143 jornadas. Es trabajo de fondo que se come horas de Calidad.": "Each private-label customer brings a technical questionnaire. In 2025 the group received 108 audits, customer visits and inspections, totalling 143 days. Preparing the evidence takes Quality time.",
  "Este llega de Freeworld Foods para el retailer del Reino Unido: 15 preguntas en inglés sobre el guisante 1 kg y el salteado de 600 g. Vuestros procedimientos están en español; da igual.": "This questionnaire comes through Freeworld Foods for a UK retailer: 15 questions in English about 1 kg peas and the 600 g vegetable mix. The source procedures can be in Spanish.",
  "Se contrasta con": "Checked against",
